ALTER TABLE public.spotify_chart_selections ADD COLUMN IF NOT EXISTS is_archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.spotify_chart_refresh_jobs ADD COLUMN IF NOT EXISTS chart_date date;
ALTER TABLE public.spotify_chart_refresh_jobs ADD COLUMN IF NOT EXISTS response_chart_date date;
ALTER TABLE public.spotify_chart_refresh_jobs ADD COLUMN IF NOT EXISTS completed_at timestamptz;
ALTER TABLE public.spotify_chart_refresh_jobs ADD COLUMN IF NOT EXISTS last_http_status integer;
ALTER TABLE public.spotify_chart_refresh_jobs ADD COLUMN IF NOT EXISTS fetched_at timestamptz;
ALTER TABLE public.spotify_chart_refresh_jobs DROP CONSTRAINT IF EXISTS spotify_chart_refresh_jobs_status_check;
ALTER TABLE public.spotify_chart_refresh_jobs ADD CONSTRAINT spotify_chart_refresh_jobs_status_check CHECK (status = ANY (ARRAY['pending','running','complete','succeeded','unavailable','retry','failed']));
UPDATE public.spotify_chart_refresh_jobs SET chart_date = CASE WHEN requested_date ~ '^\d{4}-\d{2}-\d{2}$' THEN requested_date::date ELSE NULL END WHERE chart_date IS NULL;
CREATE INDEX IF NOT EXISTS spotify_chart_refresh_jobs_claim_idx ON public.spotify_chart_refresh_jobs (status, next_attempt_at, lease_expires_at);
CREATE TABLE IF NOT EXISTS public.spotify_chart_tracking_configs (entity_uri text NOT NULL, chart_type text NOT NULL CHECK (chart_type = ANY (ARRAY['daily_top_songs','weekly_top_songs','daily_top_artists','weekly_top_artists','weekly_top_albums'])), country_code text NOT NULL, enabled boolean NOT NULL DEFAULT true, backfill_start_date date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (entity_uri, chart_type, country_code));
CREATE INDEX IF NOT EXISTS spotify_chart_tracking_configs_active_idx ON public.spotify_chart_tracking_configs (chart_type, country_code, entity_uri) WHERE enabled = true;
ALTER TABLE public.spotify_chart_backfills ADD COLUMN IF NOT EXISTS succeeded_dates integer NOT NULL DEFAULT 0;
ALTER TABLE public.spotify_chart_backfills ADD COLUMN IF NOT EXISTS unavailable_dates integer NOT NULL DEFAULT 0;
ALTER TABLE public.spotify_chart_backfills ADD COLUMN IF NOT EXISTS retry_dates integer NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS public.spotify_collection_schedule (singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton = true), enabled boolean NOT NULL DEFAULT false, local_time time NOT NULL DEFAULT '09:00', timezone text NOT NULL DEFAULT 'Africa/Algiers', next_run_at timestamptz, lease_owner text, lease_expires_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.spotify_collection_schedule (singleton) VALUES (true) ON CONFLICT (singleton) DO NOTHING;
CREATE TABLE IF NOT EXISTS public.spotify_collection_runs (id bigserial PRIMARY KEY, source text NOT NULL CHECK (source = ANY (ARRAY['scheduled','manual'])), status text NOT NULL DEFAULT 'pending' CHECK (status = ANY (ARRAY['pending','running','succeeded','partial','failed'])), started_at timestamptz, completed_at timestamptz, requested_chart_keys integer NOT NULL DEFAULT 0, completed_chart_keys integer NOT NULL DEFAULT 0, unavailable_chart_keys integer NOT NULL DEFAULT 0, failed_chart_keys integer NOT NULL DEFAULT 0, summary_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS spotify_collection_runs_created_idx ON public.spotify_collection_runs (created_at DESC, id DESC);
